import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SetPlayerGameType{GameType: packet.GameTypeSpectator}
SPECTATOR = bytes.fromhex("0c")

# generated by gophertunnel b8bd735:
# &packet.SetPlayerGameType{GameType: -1}
UNDEFINED = bytes.fromhex("01")

GOLDENS = [
    pytest.param(v2225.SetPlayerGameTypePacket(player_game_type=v2225.GameType.SPECTATOR), SPECTATOR, id="spectator"),
    pytest.param(v2225.SetPlayerGameTypePacket(player_game_type=v2225.GameType.UNDEFINED), UNDEFINED, id="undefined"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_player_game_type_is_packet_62(version):
    assert version.PACKETS[62] is version.SetPlayerGameTypePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_player_game_type_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_player_game_type_decodes_from_its_golden(packet, golden):
    assert v2225.SetPlayerGameTypePacket.from_bytes(golden) == packet


def test_set_player_game_type_rejects_an_empty_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.SetPlayerGameTypePacket.from_bytes(b"")
